const rows = $input.all();
return rows
  .filter(function(i) {
    return String(i.json.Active || 'Yes').toLowerCase() !== 'no';
  })
  .map(function(i) {
    return { json: {
      competitor: i.json.Competitor,
      url: i.json.URL,
      alertThreshold: Number(i.json.AlertThreshold || 0.12)
    }};
  });

const hashText = function(value) {
  const s = String(value || '');
  let hash = 2166136261;
  for (let i = 0; i < s.length; i++) {
    hash ^= s.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};

const stripHtml = function(html) {
  return String(html || '')
    .replace(/<!--([\s\S]*?)-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
};

const similarity = function(a, b) {
  const A = new Set(String(a).toLowerCase().split(/\s+/).filter(function(w) {
    return w.length > 2;
  }));
  const B = new Set(String(b).toLowerCase().split(/\s+/).filter(function(w) {
    return w.length > 2;
  }));
  if (!A.size && !B.size) return 1;
  let intersection = 0;
  A.forEach(function(x) {
    if (B.has(x)) intersection++;
  });
  return intersection / Math.max(1, A.size + B.size - intersection);
};

const target = $('Prepare Active Competitors').item.json;
const raw = $json.body || $json.data || $json;
const rawHtml = typeof raw === 'string' ? raw : JSON.stringify(raw);

const titleMatch = rawHtml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const title = titleMatch ? stripHtml(titleMatch[1]) : target.competitor;

const currentText = stripHtml(rawHtml).slice(0, 14000);
const currentHash = hashText(currentText);

const history = $('Load Previous Snapshots').all()
  .map(function(i) { return i.json; })
  .filter(function(row) {
    return String(row.URL || row.url || '') === String(target.url);
  });

const previous = history
  .sort(function(a, b) {
    return String(a.Timestamp || '').localeCompare(String(b.Timestamp || ''));
  })
  .slice(-1)[0];

const beforeText = previous ? String(previous.Text || '') : '';
const similarityScore = beforeText ? similarity(beforeText, currentText) : 0;
const changeRatio = beforeText ? Number((1 - similarityScore).toFixed(4)) : 0;
const threshold = Number(target.alertThreshold || 0.12);
const isBaseline = !previous;
const changed = !isBaseline && currentHash !== String(previous.Hash || '') && changeRatio >= threshold;

return {
  json: {
    competitor: target.competitor,
    url: target.url,
    alertThreshold: threshold,
    timestamp: new Date().toISOString(),
    title: title,
    hash: currentHash,
    text: currentText,
    previousHash: previous ? (previous.Hash || '') : '',
    beforeText: beforeText,
    similarityScore: similarityScore,
    changeRatio: changeRatio,
    isBaseline: isBaseline,
    changed: changed,
    eventKey: String(target.url) + '|' + currentHash
  }
};

const tick = String.fromCharCode(96);
const raw = String($json.text || $json.output || '')
  .replace(new RegExp(tick, 'g'), '')
  .replace(/^json\s*/i, '')
  .trim();
const source = $('Website Changed?').item.json;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return { json: { ...source, valid: false, validationReason: 'Gemini did not return valid JSON' } };
}

const before = String(source.beforeText || '');
const after = String(source.text || '');
const evidenceBefore = String(parsed.evidenceBefore || '');
const evidenceAfter = String(parsed.evidenceAfter || '');

const evidenceValid =
  evidenceBefore.length > 0 &&
  evidenceAfter.length > 0 &&
  before.includes(evidenceBefore) &&
  after.includes(evidenceAfter);

const impact = Number(parsed.impactScore);
const confidence = Number(parsed.confidence);

const scoresValid =
  Number.isInteger(impact) && impact >= 0 && impact <= 100 &&
  Number.isInteger(confidence) && confidence >= 0 && confidence <= 100;

const types = ['pricing', 'product', 'positioning', 'offer', 'content', 'other'];
const typeValid = types.includes(String(parsed.changeType || '').toLowerCase());

const valid = evidenceValid && scoresValid && typeValid;

return {
  json: {
    ...source,
    ...parsed,
    impactScore: impact,
    confidence: confidence,
    evidenceVerified: evidenceValid,
    valid: valid,
    validationReason: valid ? '' : 'Evidence, score, or change type validation failed',
    verifiedAt: valid ? new Date().toISOString() : ''
  }
};

const item = $input.item;
return {
  json: {
    ...item.json,
    status: 'Verified',
    verifiedAt: item.json.verifiedAt || new Date().toISOString()
  }
};
